begin;
select set_config('request.jwt.claim.sub','f9200000-0000-0000-0000-000000000001',true);
select set_config('request.jwt.claim.role','authenticated',true);
insert into branches(id,code,name) values('bb100000-0000-0000-0000-000000000001','TASK-A','Autorización ficticia A'),('bb100000-0000-0000-0000-000000000002','TASK-B','Autorización ficticia B');
create temp table actors(code text,id uuid);
insert into actors select code,gen_random_uuid() from roles where code in ('ADMIN','GERENCIA_OPERATIVA','GERENCIA_GENERAL','CALIDAD','LABORATORIO','ENCARGADA_LABORATORIO','INVENTARIO','FINANZAS','SUCURSAL','CONSULTA','TI','ASISTENTE_OPERACIONES','MEDICO_GERENTE_TECNICO','SOCIO','LOGISTICA');
insert into auth.users(id,email) select id,lower(code)||'@role-task.invalid' from actors;
insert into profiles(id,full_name,branch_id,active) select id,'Ficticio '||code,'bb100000-0000-0000-0000-000000000001',true from actors;
insert into user_roles(user_id,role_id,branch_id) select a.id,r.id,'bb100000-0000-0000-0000-000000000001' from actors a join roles r on r.code=a.code;
grant select on actors to authenticated;
create function pg_temp.ok(v boolean,label text) returns void language plpgsql as $$begin if v is distinct from true then raise exception 'FAIL %',label;end if;raise notice 'PASS %',label;end$$;
-- Reject only authorization/constraint errors, never a missing table or syntax error.
create function pg_temp.denied(stmt text,label text) returns void language plpgsql as $$begin begin execute stmt;exception when insufficient_privilege then raise notice 'PASS %',label;return;end;raise exception 'FAIL unexpectedly allowed %',label;end$$;
insert into production_batches(production_code,branch_id,source_unit_code,component_name) values('TASK-PROD','bb100000-0000-0000-0000-000000000001','TASK-U','PLASMA');
insert into blood_inventory_units(unit_code,source_unit_code,branch_id,component_name,expiry_date) values('TASK-COMP','TASK-U','bb100000-0000-0000-0000-000000000001','PLASMA',current_date+30);
insert into suppliers(supplier_code,legal_name) values('TASK-SUP','Proveedor ficticio');
insert into requisitions(requisition_code,requesting_branch_id) values('TASK-REQ','bb100000-0000-0000-0000-000000000001');
insert into competency_catalog(id,competency_code,title,category,description) values('bb300000-0000-0000-0000-000000000001','TASK-COMPETENCY','Competencia ficticia','TECNICA','Observación ficticia');
set local role authenticated;
-- All 16 canonical roles: enabled windows must have their entry permission, and admin is exclusive.
do $$declare a record;begin for a in select * from actors loop
 perform set_config('request.jwt.claim.sub',a.id::text,true);
 if exists(select 1 from role_module_access rm join user_roles ur on ur.role_id=rm.role_id join app_module_catalog m on m.route_key=rm.route_key where ur.user_id=auth.uid() and rm.enabled and m.active and not has_permission(m.permission_code)) then raise exception 'Unusable enabled window for %',a.code;end if;
 if has_permission('ACCESS_ADMIN') then raise exception 'Unexpected account administration for %',a.code;end if;
 if can_access_branch('bb100000-0000-0000-0000-000000000002') then raise exception 'Unassigned branch visible for %',a.code;end if;
 raise notice 'PASS role % has usable windows, no account admin and assigned branches only',a.code;
 end loop;end$$;
select set_config('request.jwt.claim.sub',(select id::text from actors where code='LOGISTICA'),true);
select pg_temp.ok((select count(*)=2 from vw_my_module_access where enabled),'logistics retains exactly two windows');
select pg_temp.ok((select count(*)=0 from production_batches) and (select count(*)=0 from blood_inventory_units) and (select count(*)=0 from requisitions) and (select count(*)=0 from suppliers),'logistics cannot read unrelated clinical procurement or requisition tables');
select pg_temp.ok((select count(*)=0 from vw_blood_inventory_available) and (select count(*)=0 from vw_production_summary_30d) and (select count(*)=0 from vw_approval_inbox),'views cannot bypass functional table authorization');
select pg_temp.denied($q$insert into production_batches(production_code,branch_id,source_unit_code,component_name) values('BAD','bb100000-0000-0000-0000-000000000001','U','P')$q$,'logistics cannot write production in own branch');
select pg_temp.denied($q$insert into blood_inventory_units(unit_code,source_unit_code,branch_id,component_name) values('BAD','U','bb100000-0000-0000-0000-000000000001','P')$q$,'logistics cannot insert inventory in own branch');
select pg_temp.denied($q$insert into requisitions(requisition_code,requesting_branch_id) values('BAD','bb100000-0000-0000-0000-000000000001')$q$,'logistics cannot insert requisitions in own branch');
select pg_temp.denied($q$insert into suppliers(supplier_code,legal_name) values('BAD','BAD')$q$,'logistics cannot create suppliers');
select pg_temp.denied($q$update approval_requests set status='APROBADA'$q$,'approval ledger cannot be updated directly');
select pg_temp.denied($q$insert into approval_decisions(request_id,decision,approver_id,comment,acknowledgement) values(gen_random_uuid(),'APROBAR',auth.uid(),'Falso','Falso')$q$,'approval signatures cannot be forged by direct insert');
select pg_temp.denied($q$select private.task_decide_approval_request(gen_random_uuid(),'APROBAR','Prueba','Prueba')$q$,'private API also checks decision permission');
select set_config('request.jwt.claim.sub',(select id::text from actors where code='MEDICO_GERENTE_TECNICO'),true);
select pg_temp.ok(has_permission('PRODUCTION_VIEW') and not has_permission('PRODUCTION_WRITE') and not has_permission('BLOOD_INVENTORY_WRITE'),'medical role has production consultation without inventory editing');
select pg_temp.ok((select count(*)=1 from production_batches where production_code='TASK-PROD'),'medical role can read production');
select pg_temp.denied($q$insert into production_batches(production_code,branch_id,source_unit_code,component_name) values('BAD','bb100000-0000-0000-0000-000000000001','U','P')$q$,'medical consultation cannot create production');
select pg_temp.denied($q$update blood_inventory_units set component_name='Forged' where unit_code='TASK-COMP'$q$,'release permission cannot edit inventory identity');
select set_config('request.jwt.claim.sub',(select id::text from actors where code='LABORATORIO'),true);
select pg_temp.ok(has_permission('PRODUCTION_WRITE') and not has_permission('UNIT_RELEASE'),'laboratory technician captures without technical release');
insert into production_batches(production_code,branch_id,source_unit_code,component_name) values('TASK-LAB','bb100000-0000-0000-0000-000000000001','U','PLASMA');
select pg_temp.ok((select count(*)=1 from production_batches where production_code='TASK-LAB'),'technical production capture succeeds');
select pg_temp.denied($q$update production_batches set status='DISPONIBLE' where production_code='TASK-LAB'$q$,'production capture cannot declare clinical release');
select pg_temp.denied($q$insert into production_batches(production_code,branch_id,source_unit_code,component_name) values('BAD-BRANCH','bb100000-0000-0000-0000-000000000002','U','P')$q$,'technician cannot create production in another branch');
with changed as(delete from blood_inventory_units where unit_code='TASK-COMP' returning id) select pg_temp.ok((select count(*)=0 from changed),'technician cannot delete inventory history');
select set_config('request.jwt.claim.sub',(select id::text from actors where code='INVENTARIO'),true);
select pg_temp.ok(not has_permission('PRODUCTION_WRITE'),'inventory role cannot capture technical production');
select set_config('request.jwt.claim.sub',(select id::text from actors where code='ENCARGADA_LABORATORIO'),true);
insert into requisitions(requisition_code,requesting_branch_id) values('TASK-SUPERVISOR','bb100000-0000-0000-0000-000000000001');
select pg_temp.ok(has_permission('REQUISITION_WRITE') and has_permission('COMPETENCY_ASSESS') and not has_permission('TRAINING_ADMIN') and not has_permission('COMPETENCY_WRITE'),'supervisor can request supplies and assess without training administration');
select pg_temp.ok(private.task_lab_assessment_target((select id from actors where code='LABORATORIO'),'bb100000-0000-0000-0000-000000000001') and not private.task_lab_assessment_target((select id from actors where code='FINANZAS'),'bb100000-0000-0000-0000-000000000001'),'supervisor assessment target is limited to laboratory personnel');
insert into competency_assessments(assessment_code,user_id,competency_id,branch_id,assessor_user_id,method,result,evidence_reference) select 'TASK-ASSESS',id,'bb300000-0000-0000-0000-000000000001','bb100000-0000-0000-0000-000000000001',auth.uid(),'Observación','COMPETENTE','EVIDENCIA-FICTICIA' from actors where code='LABORATORIO';
select pg_temp.ok((select count(*)=1 from competency_assessments where assessment_code='TASK-ASSESS'),'supervisor can register a laboratory assessment');
select pg_temp.denied($q$insert into competency_assessments(assessment_code,user_id,competency_id,branch_id,assessor_user_id,method,result,evidence_reference) select 'BAD-ASSESS',id,'bb300000-0000-0000-0000-000000000001','bb100000-0000-0000-0000-000000000001',auth.uid(),'Observación','COMPETENTE','EVIDENCIA' from actors where code='FINANZAS'$q$,'supervisor cannot assess an unrelated finance role');
select set_config('request.jwt.claim.sub',(select id::text from actors where code='ASISTENTE_OPERACIONES'),true);
select pg_temp.ok(has_permission('COMMERCIAL_WRITE') and not has_permission('UNIT_RELEASE') and not has_permission('COLLECTIONS_WRITE'),'assistant can record commercial follow-up without clinical release or collections');
-- Approval request creation is functional, decisions independent, payload immutable, execution rechecked.
select set_config('request.jwt.claim.sub',(select id::text from actors where code='GERENCIA_OPERATIVA'),true);
select create_approval_request('DAILY_CLOSE','bb100000-0000-0000-0000-000000000001',null,null,'TASK-APPROVAL','Cierre ficticio','Verificación de autorización','{}') as request_id \gset
select pg_temp.denied(format('update approval_requests set payload=%L where id=%L','{"notes":"Forged"}',:'request_id'),'request payload cannot be edited outside controlled flow');
select pg_temp.denied(format('select decide_approval_request(%L,%L,%L,%L)',:'request_id','APROBAR','Prueba','Prueba'),'missing or self decision permission cannot bypass independence');
reset role;select set_config('request.jwt.claim.sub','f9200000-0000-0000-0000-000000000001',true);
insert into auth.users(id,email) values('bb200000-0000-0000-0000-000000000099','reviewer@role-task.invalid');
insert into profiles(id,full_name,branch_id,active) values('bb200000-0000-0000-0000-000000000099','Revisor ficticio','bb100000-0000-0000-0000-000000000001',true);
insert into user_roles(user_id,role_id,branch_id) select 'bb200000-0000-0000-0000-000000000099',id,'bb100000-0000-0000-0000-000000000001' from roles where code='GERENCIA_OPERATIVA';
set local role authenticated;select set_config('request.jwt.claim.sub','bb200000-0000-0000-0000-000000000099',true);
select pg_temp.ok(decide_approval_request(:'request_id','APROBAR','Revisión independiente','Confirmo revisión')='APROBADA','independent authorized decision succeeds');
select pg_temp.ok((select approvals_count=1 and status='APROBADA' from approval_requests where id=:'request_id'),'approved status derives from actual decisions');
select pg_temp.ok(execute_approved_action(:'request_id') ? 'daily_close_id','authorized execution succeeds through controlled ledger API');
select pg_temp.ok((select status='EJECUTADA' and executed_by=auth.uid() from approval_requests where id=:'request_id'),'execution preserves actual actor');
select set_config('request.jwt.claim.sub','f9200000-0000-0000-0000-000000000001',true);
select pg_temp.ok((select count(*)=66 and bool_and(enabled) from vw_my_module_access),'super retains all 66 windows');
select pg_temp.ok(not exists(select 1 from app_permissions where active and not has_permission(permission_code)),'super retains every active permission');
reset role;
update profiles set active=false where id=(select id from actors where code='LABORATORIO');
set local role authenticated;select set_config('request.jwt.claim.sub',(select id::text from actors where code='LABORATORIO'),true);
select pg_temp.ok((select count(*)=0 from production_batches),'inactive profile cannot read production');
reset role;set local role anon;
select pg_temp.denied($q$select create_approval_request('DAILY_CLOSE',null,null,null,null,'X','X','{}')$q$,'anonymous cannot call approval APIs');
rollback;
